struct student{
    int roll;
    int maths;
    int physics;
    int chemistry;
};

typedef struct student Student;

void copy(Student *a, int i, int j){
    int t;
    t=a[i].roll;
    a[i].roll=a[j].roll;
    a[j].roll=t;
    t=a[i].maths;
    a[i].maths=a[j].maths;
    a[j].maths=t;
    t=a[i].chemistry;
    a[i].chemistry=a[j].chemistry;
    a[j].chemistry=t;
    t=a[i].physics;
    a[i].physics=a[j].physics;
    a[j].physics=t;
}



void sort2(Student *a, int start, int end){
    int i,j;
    for(i=start;i<=end;i++){
        for(j=i+1;j<=end;j++){
            if(((a[i]).physics)>((a[j]).physics)){
                copy(a,i,j);
            }
        }
    }
}

void sortm(Student *a, int n){
    int i,j;
    for(i=0;i<n;i++){
        for(j=i+1;j<n;j++){
            if(((a[i]).maths)>((a[j]).maths)){
                copy(a,i,j);
            }
        }
    }
}

