#include <stdio.h>
#include <stdlib.h>
typedef struct std
{
    int rn,m,p,c;
}std;
void scanit(std* s)
{
    scanf("%d %d %d %d",&(s->rn),&(s->m),&(s->p),&(s->c));
}
void swap(std *a,std *b)
{
    std c=*a;
    *a=*b;
    *b=c;
}
int main() {
    int n;
    scanf("%d",&n);
    std* s=(std*)calloc(n,sizeof(std));
    for(int i=0;i<n;i++) scanit(s+i);

    for(int i=0;i<n;i++)
    {
        int max=(s+i)->m;int indx=i;
        for(int j=i+1;j<n;j++)
        {
            if(((s+j)->m)>max)
            {
                indx=j;
                max=(s+j)->m;
            }
            else if(((s+j)->m)==max)
            {
                if(((s+j)->p)>((s+indx)->p)) indx=j;
                else if(((s+j)->p)==((s+indx)->p))
                {
                    if(((s+j)->c)>((s+indx)->p)) indx=j;
                }
            }
        }
        swap(s+i,s+indx);
    }
    for(int k=0;k<n;k++) printf("%d\n",(s+k)->rn);
    return 0;
}
